const std::vector<ReferencePage>& NativeDevPages() {
    static const std::vector<ReferencePage> pages = [] {
        std::vector<ReferencePage> result{
            {"dev.retail", "start", true, {}},
            {"dev.retail.gp_missions_and_ow_activities", "GP Missions and OW Activities", true, {}},
            {"dev.retail.start_pre_branch", "start_pre_branch", true, {}},
            {"dev.retail.silver_path", "Silver Path", true, {}},
            {"dev.retail.act_1_missions", "Act 1 Missions", true, {}},
            {"dev.retail.act_2_missions", "Act 2 Missions", true, {}},
            {"dev.retail.act_3_missions", "Act 3 Missions", true, {}},
            {"dev.retail.bases", "Bases", true, {}},
            {"dev.retail.wingsuit_challenges", "Wingsuit Challenges", true, {}},
            {"dev.retail.wraith_villain_arc", "Wraith Villain Arc", true, {}},
            {"dev.retail.mysterio_villain_arc", "Mysterio Villain Arc", true, {}},
            {"dev.retail.events_crimes", "Events/Crimes", true, {}},
            {"dev.retail.beautiful_corner", "Beautiful Corner", true, {}},
            {"dev.retail.harlem_quest_arc", "Harlem Quest Arc", true, {}},
            {"dev.retail.emf_activities", "EMF Activities", true, {}},
            {"dev.retail.prowler_tech_stashes", "Prowler Tech Stashes", true, {}},
            {"dev.retail.sandman_collectible", "Sandman Collectible", true, {}},
            {"dev.retail.fnsm_app", "FNSM App", true, {}},
            {"dev.retail.tracking_demo", "TRACKING Demo", true, {}},
            {"dev.retail.connected_playthrough", "Connected Playthrough", true, {}},
            {"dev.retail.combat_deliverables", "Combat Deliverables", true, {}},
            {"dev.retail.audio_deliverables", "Audio Deliverables", true, {}},
            {"dev.retail.ux_test", "UX TEST", true, {}},
            {"dev.retail.beetle_villain_arc", "Beetle Villain Arc", true, {}},
            {"dev.retail.2023_press_preview", "2023 Press Preview", true, {}},
        };
        for (const auto& option : NativeDevOptions()) {
            for (auto& page : result) {
                if (page.id != option.pageId) continue;
                page.rows.push_back({option.label, option.targetPageId, false});
                break;
            }
        }
        return result;
    }();
    return pages;
}

const NativeDevOption* FindNativeDevOption(const std::string& pageId,
                                         const std::string& label) {
    for (const auto& option : NativeDevOptions())
        if (option.pageId == pageId && option.label == label) return &option;
    return nullptr;
}
